// === Tab: mySketch ===
// sin, cos, ellipse, generative, monochrome
// let click to redraw.
// let on let Pickover's let attractor.
// let drawing let from let Henstridge: www.altix.ovh/fac/Popcorn.java
// http://paulbourke.net/fractals/popcorn/
// http://www.iquilezles.org/www/articles/popcorns/popcorns.html
// https://element90.wordpress.com/2012/01/10/pickover-popcorn/


let p;
let f1, f2, f3, f4;
let hu = 0;

function setup() {
  createCanvas(1112, 834);
	colorMode(HSB, 255);
  p = new PopCorn();
  f1 = new SinOrCos();
  f2 = new SinOrCos();
  f3 = new SinOrCos();
  f4 = new SinOrCos();
	f5 = new SinOrCos();
	f6 = new SinOrCos();
	hu = random(255);
  noStroke();
  background(hu, 50, 255);
}

function draw() {
  p.run();
}


class PopCorn {
  dots = 50, res = 4, j, i, count;
  t = 3, b = -3, l = -3.0, r = 3.0;
  x, y, xnew, ynew;
  mult = 1.5, h = .085;
  howMany = 1000;

  function run() {
    j += res;
    for (i = 0; i <= width; i += res) {
      x = float(i) / width * (r - l) + l;
      y = float(j) / height * (b - t) + t;
      for (k = 0; k < dots; k++) {
        xnew = x - h * f1.calc(y + f2.calc(PI * mult * y));
        ynew = y - h * f3.calc(x + f4.calc(PI * x));
        x = xnew; 
        y = ynew;
        fill(hu, 255, 50);
        ellipse((x - l)/(r - l) * width, (y - t)/(b - t) * height, .5, .5);
        count++;
      }
    }
    if (j >= howMany) {
      noLoop();
      //fill(100);
      //text(count, 30, height-30);
    }
  }
}

function mousePressed() {
  background("#EAEDFF");
  p.mult = random(1, 5);
  p.h = random(.05, .2);
  p.j = 0;
  p.count = 0;
  p.howMany = random(height/5, height);
  f1 = new SinOrCos();
  f2 = new SinOrCos();
  f3 = new SinOrCos();
  f4 = new SinOrCos();
	f5 = new SinOrCos();
	f6 = new SinOrCos();
  loop();
}

class SinOrCos {
  let which = int(random(0, 2));
  calc(rad) {
    if (which == 0) return sin(rad);
    else return cos(rad);
  }

}

